// ─── File: src/main/java/com/bank/single/model/BankAccount.java ───
// ONE CLASS — demonstrates ALL FOUR OOP PILLARS
package com.bank.single.model;

import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;

public class BankAccount /* implicitly extends java.lang.Object — INHERITANCE! */ {

    // ═══════════════════════════════════════════════════════════════
    // PILLAR 1: ENCAPSULATION — private fields, controlled access
    // ═══════════════════════════════════════════════════════════════
    private final String accountId;           // private + final = immutable
    private BigDecimal balance;               // private = only methods can change
    private final String holderName;          // private + final
    private final List<String> transactionLog = new ArrayList<>();  // private

    public BankAccount(String accountId, String holderName, BigDecimal initialBalance) {
        if (accountId == null || accountId.isBlank()) throw new IllegalArgumentException("accountId required");
        if (initialBalance.signum() < 0) throw new IllegalArgumentException("Cannot start with negative balance");
        this.accountId = accountId;
        this.holderName = holderName;
        this.balance = initialBalance;
        transactionLog.add("OPENED: Rs." + initialBalance + " at " + LocalDateTime.now());
    }

    // ═══════════════════════════════════════════════════════════════
    // PILLAR 2: ABSTRACTION — public methods hide private complexity
    // ═══════════════════════════════════════════════════════════════

    // PUBLIC: what the caller sees (WHAT)
    // PRIVATE: what's hidden inside (HOW)

    // ═══════════════════════════════════════════════════════════════
    // PILLAR 3: POLYMORPHISM (compile-time) — method OVERLOADING
    // ═══════════════════════════════════════════════════════════════

    // Overload 1: deposit with just amount
    public void deposit(BigDecimal amount) {
        validatePositive(amount);              // hidden step 1
        updateBalance(amount);                 // hidden step 2
        logTransaction("CREDIT", amount, "");  // hidden step 3
    }

    // Overload 2: deposit with amount + narration
    public void deposit(BigDecimal amount, String narration) {
        validatePositive(amount);
        updateBalance(amount);
        logTransaction("CREDIT", amount, narration);
    }

    // Overload 3: deposit with amount + narration + reference
    public void deposit(BigDecimal amount, String narration, String reference) {
        validatePositive(amount);
        updateBalance(amount);
        logTransaction("CREDIT", amount, narration + " [REF:" + reference + "]");
    }

    // Withdrawal (single version for simplicity)
    public void withdraw(BigDecimal amount) {
        validatePositive(amount);
        if (balance.compareTo(amount) < 0) {
            throw new IllegalStateException("Insufficient balance: Rs." + balance + " for Rs." + amount);
        }
        balance = balance.subtract(amount);
        logTransaction("DEBIT", amount, "");
    }

    // ═══ ABSTRACTION: private helper methods (hidden from caller) ═══
    private void validatePositive(BigDecimal amount) {
        if (amount == null || amount.signum() <= 0) {
            throw new IllegalArgumentException("Amount must be positive, got: " + amount);
        }
    }

    private void updateBalance(BigDecimal amount) {
        balance = balance.add(amount);
    }

    private void logTransaction(String type, BigDecimal amount, String narration) {
        String entry = type + ": Rs." + amount;
        if (narration != null && !narration.isBlank()) entry += " (" + narration + ")";
        entry += " at " + LocalDateTime.now();
        transactionLog.add(entry);
    }

    // ═══════════════════════════════════════════════════════════════
    // PILLAR 4: INHERITANCE from Object — OVERRIDE toString/equals/hashCode
    //           This is also RUNTIME POLYMORPHISM!
    // ═══════════════════════════════════════════════════════════════

    @Override
    public String toString() {
        // Overrides Object.toString() → "com.bank.single.model.BankAccount@1a2b3c"
        // Now returns: "SAV2001 (Rajesh Kumar): Rs.125000.50"
        return accountId + " (" + holderName + "): Rs." + balance;
    }

    @Override
    public boolean equals(Object other) {
        // Overrides Object.equals() which does reference comparison (==)
        // Now: two BankAccounts with same accountId are EQUAL (business identity)
        if (this == other) return true;
        if (!(other instanceof BankAccount that)) return false;
        return Objects.equals(accountId, that.accountId);
    }

    @Override
    public int hashCode() {
        return Objects.hash(accountId);
    }

    // Getters — controlled read access (encapsulation)
    public String getAccountId() { return accountId; }
    public String getHolderName() { return holderName; }
    public BigDecimal getBalance() { return balance; }
    public List<String> getTransactionLog() {
        return Collections.unmodifiableList(transactionLog);  // read-only view!
    }
}
```

