package com.bank.single;

import com.bank.single.model.BankAccount;
import java.math.BigDecimal;

public class SingleClassApp {
    public static void main(String[] args) {
        BankAccount account = new BankAccount("SAV2001", "Rajesh Kumar", new BigDecimal("125000.50"));

        // POLYMORPHISM: three overloaded deposit methods
        account.deposit(new BigDecimal("5000"));                                    // overload 1
        account.deposit(new BigDecimal("85000"), "Salary credit");                  // overload 2
        account.deposit(new BigDecimal("1000"), "Gift", "NEFT-UTR-ABC123");        // overload 3

        // INHERITANCE: toString() overridden from Object
        System.out.println(account);  // "SAV2001 (Rajesh Kumar): Rs.216000.50"

        // ENCAPSULATION: cannot access balance directly
        // account.balance = 999999;  // COMPILE ERROR — private!

        // ABSTRACTION: deposit() hides validate + update + log steps
        // Caller sees ONE method call. Internally: 3 steps happen.

        // Transaction log (encapsulated — returned as unmodifiable)
        account.getTransactionLog().forEach(System.out::println);
    }
}
