// ─── File: src/test/java/com/bank/single/model/SingleClassOopTest.java ───
package com.bank.single.model;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.HashSet;
import java.util.Set;
import static org.assertj.core.api.Assertions.*;

class SingleClassOopTest {

    // ═══ PILLAR 1: ENCAPSULATION ═══
    @Test
    void encapsulation_balanceChangesOnlyThroughMethods() {
        BankAccount account = new BankAccount("SAV001", "Rajesh", new BigDecimal("10000"));
        // account.balance = 999;  // Won't compile — balance is private!
        account.deposit(new BigDecimal("5000"));
        assertThat(account.getBalance()).isEqualByComparingTo("15000");
    }

    @Test
    void encapsulation_negativeDepositRejected() {
        BankAccount account = new BankAccount("SAV001", "Rajesh", new BigDecimal("10000"));
        assertThatThrownBy(() -> account.deposit(new BigDecimal("-100")))
            .isInstanceOf(IllegalArgumentException.class)
            .hasMessageContaining("positive");
    }

    @Test
    void encapsulation_transactionLogIsUnmodifiable() {
        BankAccount account = new BankAccount("SAV001", "Rajesh", new BigDecimal("10000"));
        assertThatThrownBy(() -> account.getTransactionLog().add("HACK!"))
            .isInstanceOf(UnsupportedOperationException.class);
    }

    // ═══ PILLAR 2: ABSTRACTION ═══
    @Test
    void abstraction_depositHidesInternalSteps() {
        BankAccount account = new BankAccount("SAV001", "Rajesh", new BigDecimal("10000"));
        account.deposit(new BigDecimal("5000"), "Salary");
        // Caller called ONE method. Internally: validate + updateBalance + logTransaction
        // Caller doesn't know about private validatePositive(), updateBalance(), logTransaction()
        assertThat(account.getBalance()).isEqualByComparingTo("15000");
        assertThat(account.getTransactionLog()).anyMatch(log -> log.contains("CREDIT") && log.contains("Salary"));
    }

    // ═══ PILLAR 3: POLYMORPHISM (compile-time — overloading) ═══
    @Test
    void polymorphism_threeOverloadedDepositMethods() {
        BankAccount account = new BankAccount("SAV001", "Rajesh", new BigDecimal("10000"));

        account.deposit(new BigDecimal("1000"));                            // overload 1
        account.deposit(new BigDecimal("2000"), "Salary");                  // overload 2
        account.deposit(new BigDecimal("3000"), "Bonus", "NEFT-UTR-XYZ");  // overload 3

        assertThat(account.getBalance()).isEqualByComparingTo("16000");  // 10000 + 1000 + 2000 + 3000
        // Three DIFFERENT method signatures, ONE method name — compile-time polymorphism!
    }

    // ═══ PILLAR 4: INHERITANCE (from Object) + RUNTIME POLYMORPHISM ═══
    @Test
    void inheritance_toStringOverriddenFromObject() {
        BankAccount account = new BankAccount("SAV001", "Rajesh", new BigDecimal("10000"));
        String str = account.toString();
        // If NOT overridden: "com.bank.single.model.BankAccount@1a2b3c"
        // Overridden: "SAV001 (Rajesh): Rs.10000"
        assertThat(str).contains("SAV001").contains("Rajesh").contains("10000");
        assertThat(str).doesNotContain("@");  // proves toString was overridden!
    }

    @Test
    void inheritance_equalsOverriddenFromObject() {
        BankAccount a = new BankAccount("SAV001", "Rajesh", new BigDecimal("10000"));
        BankAccount b = new BankAccount("SAV001", "Rajesh Copy", new BigDecimal("20000"));
        // Object.equals: a == b → false (different references)
        // Overridden equals: same accountId → true
        assertThat(a).isEqualTo(b);  // business equality by accountId!
    }

    @Test
    void inheritance_hashCodeConsistentWithEquals() {
        BankAccount a = new BankAccount("SAV001", "Rajesh", new BigDecimal("10000"));
        BankAccount b = new BankAccount("SAV001", "Copy", new BigDecimal("20000"));
        assertThat(a.hashCode()).isEqualTo(b.hashCode());  // equal objects → same hash

        // Works in HashSet:
        Set<BankAccount> set = new HashSet<>();
        set.add(a);
        set.add(b);  // same accountId → set treats as duplicate
        assertThat(set).hasSize(1);  // only ONE entry — equals+hashCode work!
    }

    @Test
    void inheritance_runtimePolymorphismViaObjectReference() {
        Object ref = new BankAccount("SAV001", "Rajesh", new BigDecimal("10000"));
        // Variable type: Object. Actual type: BankAccount.
        String str = ref.toString();
        // JVM dispatches to BankAccount.toString() at RUNTIME — NOT Object.toString()!
        assertThat(str).contains("SAV001");  // proves RUNTIME POLYMORPHISM!
    }

    @Test
    void inheritance_bankAccountIsAnObject() {
        BankAccount account = new BankAccount("SAV001", "Rajesh", BigDecimal.ZERO);
        assertThat(account).isInstanceOf(Object.class);  // BankAccount IS-A Object
        // Inherited from Object: toString, equals, hashCode, getClass, wait, notify, etc.
    }

    // ═══ ALL FOUR PILLARS IN ONE CLASS — SUMMARY ═══
    @Test
    void allFourPillarsInOneClass() {
        // ONE class: BankAccount
        // NO extends, NO implements, NO sibling classes
        // Yet ALL FOUR OOP pillars are present:

        BankAccount account = new BankAccount("SAV001", "Rajesh", new BigDecimal("10000"));

        // 1. ENCAPSULATION: private balance, controlled through methods
        account.deposit(new BigDecimal("5000"));
        assertThat(account.getBalance()).isEqualByComparingTo("15000");

        // 2. ABSTRACTION: deposit() hides validate + update + log
        account.deposit(new BigDecimal("1000"), "Test");
        assertThat(account.getTransactionLog().size()).isGreaterThan(1);

        // 3. POLYMORPHISM (compile-time): three overloaded deposit methods
        account.deposit(new BigDecimal("100"));
        account.deposit(new BigDecimal("100"), "Narration");
        account.deposit(new BigDecimal("100"), "Narration", "REF-001");

        // 4. INHERITANCE + POLYMORPHISM (runtime): overridden toString from Object
        Object ref = account;
        assertThat(ref.toString()).contains("SAV001");  // runtime dispatch!

        // (Recommended) ALL FOUR PILLARS PROVEN in ONE class!
    }
}
